        data_column_sidecar,
        true,
        DataColumnSidecarOrigin::ExecutionLayer,
    )
}

pub fn on_gossip_blob_sidecar(
    &self,
    blob_sidecar: Arc<BlobSidecar<P>>,
    subnet_id: SubnetId,
    gossip_id: GossipId,
    block_seen: bool,
) {
    self.spawn_blob_sidecar_task(
        blob_sidecar,
        block_seen,
        BlobSidecarOrigin::Gossip(subnet_id, gossip_id),
    )
}

