    pub block: Arc<SignedBeaconBlock<P>>,
    pub origin: BlockOrigin,
    pub processing_timings: ProcessingTimings,
    pub metrics: Option<Arc<Metrics>>,
}

impl<P: Preset, E: ExecutionEngine<P> + Send, W> Run for BlockTask<P, E, W> {
    fn run(self) {
        let Self {
            store_snapshot,
